import{_ as e,o as r,c as t,x as o}from"./chunks/framework.DzQQ_lrg.js";const u=JSON.parse('{"title":"伦敦出租车学员：没拿到执照，就等于没有学会吗？","description":"用伦敦出租车学员的纵向研究，区分资格结果、具体任务表现、脑结构记录与学习机制。","frontmatter":{"title":"伦敦出租车学员：没拿到执照，就等于没有学会吗？","description":"用伦敦出租车学员的纵向研究，区分资格结果、具体任务表现、脑结构记录与学习机制。","kind":"真实案例","source_type":"期刊研究论文及其补充材料","concepts":["carried-learning"]},"headers":[],"relativePath":"cases/london-taxi-learning.md","filePath":"cases/london-taxi-learning.md"}'),i={name:"cases/london-taxi-learning.md"};function n(l,a,s,h,p,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="伦敦出租车学员-没拿到执照-就等于没有学会吗" tabindex="-1">伦敦出租车学员：没拿到执照，就等于没有学会吗？ <a class="header-anchor" href="#伦敦出租车学员-没拿到执照-就等于没有学会吗" aria-label="Permalink to &quot;伦敦出租车学员：没拿到执照，就等于没有学会吗？&quot;">​</a></h1><p>想在伦敦开出租车，要先记住查令十字火车站方圆6英里内约2.5万条街道和数千处地点，通常要学三至四年，再通过一系列严格考核才能拿到执照。Woollett与Maguire在2011年发表的研究，在训练开始时和三至四年后，对同一批学员和对照者各测了一次。本页的事实都出自这篇论文及其补充材料。[1，第2109页]</p><h2 id="研究怎样做" tabindex="-1">研究怎样做 <a class="header-anchor" href="#研究怎样做" aria-label="Permalink to &quot;研究怎样做&quot;">​</a></h2><p>第一次测试有79名男性学员和31名男性对照者，内容是一组记忆测验和脑结构磁共振扫描；复测距第一次的时间，三组平均为33—36个月。[1，第2109、2111页]</p><p>79名学员中，39人取得资格并参加复测；20人没有取得资格（停止训练或未通过考核），但参加了复测；另外20人没有回来，其中2人已取得资格，18人停止训练或从未参加考核。31名对照者全部参加复测。按论文的统计，学员中51.9%（41人）取得资格；下文的结果只来自参加复测的39人、20人和31人。[1，第2109页]</p><h2 id="论文记录了什么" tabindex="-1">论文记录了什么 <a class="header-anchor" href="#论文记录了什么" aria-label="Permalink to &quot;论文记录了什么&quot;">​</a></h2><p>训练前，三组在各项记忆测验和灰质体积上都没有显著差别。[1，第2110页] 复测时，论文报告了下面三项结果。</p><p><strong>伦敦地标判断</strong>：看一张地标照片，判断另外两个地标中哪一个离它的直线距离更近，共10题。取得资格的学员和没有取得资格的学员都显著优于对照者（p均为0.003；两组学员均值为8.51分和8.75分，对照者7.32分）。论文没有报告两组学员之间的比较。[1，第2111页；2]</p><p><strong>复杂图形延迟回忆</strong>：临摹一幅复杂图形，30分钟后凭记忆画出，满分36分。取得资格的学员显著低于对照者（均值21.93对25.77，p=0.01）；没有取得资格的学员与对照者没有显著差别（均值22.60，p=0.14）。[1，第2111页；2]</p><p><strong>脑结构</strong>：取得资格的学员，双侧后部海马的灰质体积比训练前增加；没有取得资格的学员和对照者，都没有发现显著的灰质体积变化。[1，第2111页]</p><p>两项行为结果都是复测时各组之间的比较。前后两次用的是不同版本的测验，论文和补充材料都没有给出每个人前后分数的变化。[2]</p><h2 id="作者的解释与研究的限制" tabindex="-1">作者的解释与研究的限制 <a class="header-anchor" href="#作者的解释与研究的限制" aria-label="Permalink to &quot;作者的解释与研究的限制&quot;">​</a></h2><p>作者认为，掌握伦敦的布局带来了后部海马的结构变化和记忆表现的改变，并提出一个领域的记忆改善“可能”以别处的记忆表现为代价；作者推测这与前部海马有关，但这项研究没有观察到前部海马灰质减少。灰质为什么增加，论文说明常规结构磁共振无法直接回答，神经发生、突触形成、树突分支和胶质细胞变化只是依据动物研究列出的候选。[1，第2111—2112页]</p><p>这些结论有几项限制。谁受训、谁最后取得资格，都不是随机分配的；参与者全部是男性；20名学员没有参加复测，论文的各项比较只含参加复测的90人。两组学员的总训练时间没有显著差别，但取得资格者每周训练约34.6小时，未取得资格者约16.7小时，参加考核的次数平均是15.6次对2.6次，两组之间不只差一张执照。作者也指出，取得资格者可能本来就有不同的遗传倾向，先天与后天的问题仍然开放。[1，第2109—2111、2113页]</p><h2 id="用三个问题读这项研究" tabindex="-1">用三个问题读这项研究 <a class="header-anchor" href="#用三个问题读这项研究" aria-label="Permalink to &quot;用三个问题读这项研究&quot;">​</a></h2><p>以下是本页借《Xikari-条件结构与转化论》的概念提出的读法；论文没有使用这些概念，原文也没有讨论这项研究。</p><p><strong>没有取得资格，能不能说什么也没学到？</strong> 不能。这组学员复测时在地标判断上显著优于对照者，尽管没有测到灰质变化；资格、任务表现和脑影像是三种记录，不能互相代替。反过来，一项10题任务上的组间优势，也不说明达到了执业要求。</p><p><strong>有了学习的证据，是否就识别了反馈介导学习？</strong> 没有。原文承认一般学习“可以由相应领域的证据得到支持”，“不必先取得本框架的正式机制实例身份”。反馈介导学习是更窄的机制主张：返回造成可定位的更新，更新被保留并在后续轮次实际调用，预定任务的结果因此不同；因果主张还要处理选择、失访与测量改变。论文没有记录哪一次练习或考核的返回改变了什么，上一节的限制又正落在选择、失访和测验版本上，所以这条机制在这里是未识别，不是已证实或已否定。<a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-3">阅读原文：§6.3反馈介导学习</a></p><p><strong>训练了三四年，是否就检验了历史增量？</strong> 没有。原文分开三个问题：先前经历怎样形成当前状态，当前载体怎样保留并继续影响结果，给定当前状态之后历史是否还提供额外的信息或作用；“前两项可以成立而第三项不成立，也不能由第三项未获支持反推前两项成立。”第三项由G3检验。这项研究没有在控制当前状态之后比较历史带来的增量，所以对第三项既不提供支持，也不提供否定；已有的学习证据并不因此作废。<a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-5">阅读原文：§4.5历史形成、当前载体与G3条件增量</a></p><h2 id="对照概念与原文" tabindex="-1">对照概念与原文 <a class="header-anchor" href="#对照概念与原文" aria-label="Permalink to &quot;对照概念与原文&quot;">​</a></h2><ul><li><a href="/xi-kari-skill/handbook/concepts/history.html">留下记录，与真正学会了什么</a></li><li><a href="/xi-kari-skill/handbook/theory/part-02.html#section-2-1-1">原文§2.1.1：领域证据与正式实例资格</a></li><li><a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-5">原文§4.5：历史形成、当前载体与G3条件增量</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-3">原文§6.3：反馈介导学习</a></li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ol><li>Katherine Woollett、Eleanor A. Maguire（2011），Acquiring “the Knowledge” of London’s Layout Drives Structural Brain Changes，<em>Current Biology</em> 21（24），2109—2114，DOI <a href="https://doi.org/10.1016/j.cub.2011.11.018" target="_blank" rel="noreferrer">10.1016/j.cub.2011.11.018</a>。开放获取全文见<a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC3268356/" target="_blank" rel="noreferrer">PMC3268356</a>，带期刊页码的版本见<a href="https://www.fil.ion.ucl.ac.uk/Maguire/WoollettMaguireCBDec2011.pdf" target="_blank" rel="noreferrer">作者实验室托管的PDF</a>。</li><li>同一论文的补充材料Document S1（表S1与补充实验方法，共5页），<a href="https://ars.els-cdn.com/content/image/1-s2.0-S096098221101267X-mmc1.pdf" target="_blank" rel="noreferrer">出版社附件</a>。</li></ol>',23)])])}const k=e(i,[["render",n]]);export{u as __pageData,k as default};
